insert into audit.data_quality_issues (severity,domain,table_name,record_key,rule_code,description,status,details) select 'warning','provenance','raw.documents','legacy_backtest_xlsx','LEGACY_PARAMETERS_INCOMPLETE','Frozen outputs exist, but the historical workbook does not contain the full executable parameter set for all four valuations.','open','{"effect":"legacy run can be audited as a frozen output but not exactly recalculated from assumptions","resolution":"rebuild future snapshots from explicit run_assumptions"}'::jsonb where not exists (select 1 from audit.data_quality_issues where rule_code='LEGACY_PARAMETERS_INCOMPLETE' and record_key='legacy_backtest_xlsx');
insert into audit.data_quality_issues (severity,domain,table_name,record_key,rule_code,description,status,details) select 'warning','provenance','raw.documents','BYD_2021:B12','PHASE_SOURCE_CONTAMINATION','The legacy BYD source cell mixed a 2026 PDF with Phase-A 2021 sources; the 2026 URL is excluded from the new Phase-A manifest.','open','{"excluded":"https://static.cninfo.com.cn/finalpage/2026-08-29/1225531835.PDF"}'::jsonb where not exists (select 1 from audit.data_quality_issues where rule_code='PHASE_SOURCE_CONTAMINATION' and record_key='BYD_2021:B12');
insert into audit.data_quality_issues (severity,domain,table_name,record_key,rule_code,description,status,details) select 'warning','provenance','raw.documents','CMB_2021:B12','PHASE_SOURCE_CONTAMINATION','The legacy CMB source cell mixed a 2026 PDF with Phase-A 2021 sources; the 2026 URL is excluded from the new Phase-A manifest.','open','{"excluded":"http://static.sse.com.cn/disclosure/listedinfo/announcement/c/new/2026-08-29/600036_20260829_94TO.pdf"}'::jsonb where not exists (select 1 from audit.data_quality_issues where rule_code='PHASE_SOURCE_CONTAMINATION' and record_key='CMB_2021:B12');
insert into audit.data_quality_issues (severity,domain,table_name,record_key,rule_code,description,status,details) select 'info','backtest','pit.corporate_actions','gate0_legacy_actions','CORPORATE_ACTION_PROXY_DATES','Legacy workbook stored month-level event dates and proxy reinvestment prices; database dates are month-end placeholders with explicit metadata.','open','{"daily_path_available":false,"mdd_eligible":false}'::jsonb where not exists (select 1 from audit.data_quality_issues where rule_code='CORPORATE_ACTION_PROXY_DATES' and record_key='gate0_legacy_actions');
insert into audit.data_quality_issues (severity,domain,table_name,record_key,rule_code,description,status,details) select 'warning','pit','audit.data_snapshots','gate0_legacy_snapshot','LEGACY_FROZEN_NOT_NATIVE_PIT','The four-company 2021 snapshot is a migration bridge reconstructed from a 2026 workbook. It is not equivalent to native archival evidence captured in 2021.','open','{"eligible_for_architecture_golden_test":true,"eligible_for_formal_strategy_evidence":false,"required_resolution":"rebuild each historical snapshot from contemporaneous official filings and market data"}'::jsonb where not exists (select 1 from audit.data_quality_issues where rule_code='LEGACY_FROZEN_NOT_NATIVE_PIT' and record_key='gate0_legacy_snapshot');
